// Built with --obfuscate --dart-define=AI_KEY=...
const aiKey = String.fromEnvironment('AI_KEY');

Future<String> summarize(Http http, String text) {
  return http.post(
    Uri.parse('https://api.ai-vendor.example/v1/summarize'),
    // Ends up in libapp.so and in every request
    headers: {'Authorization': 'Bearer $aiKey'},
    body: jsonEncode({'text': text}),
  );
}

// The vendor key lives only on your server
Future<String> summarize(Http http, Session session, String text) {
  return http.post(
    Uri.parse('https://api.yourapp.example/summaries'),
    // A short-lived token for this user, not a shared secret
    headers: {'Authorization': 'Bearer ${session.accessToken}'},
    body: jsonEncode({'text': text}),
  );
}
